	// EVOLVE-BLOCK-START
	scores := make(map[string]float64, len(snapshots))

	// Adaptive weight multipliers based on request context
	prefixBoost := 1.0
	loadBoost := 1.0

	// Sessions benefit strongly from prefix cache hits
	if req.SessionID != "" {
		prefixBoost = 3.5
		loadBoost = 0.4
	}

	// Large inputs benefit more from prefix caching
	inputLen := len(req.InputTokens)
	if inputLen > 512 {
		prefixBoost *= 1.8
	} else if inputLen > 256 {
		prefixBoost *= 1.3
	}

